      "kind": "configured Hub model/tokenizer",
      "materialization": "No artifact copy; original Hub IDs passed unchanged.",
      "response_cache": "Fresh output/sample-cache/Hub ID/hash.",
      "source": "Response cache isolated; ordinary HF model download/cache outside this response-cache scope unchanged."
    }
  ],
  "not_selected": [
    {
      "approach": "cache_dir only",
      "reason": "Does not contain absolute local model_name; red persists/source writes."
    },
    {
      "approach": "postconstructor _cache=None or cache.cache_dir/existing_indices mutation",
      "reason": "Private API and too late for constructor I/O; read-only local source still fails."
    },
    {
      "approach": "config nonce only",
      "reason": "Changes hash but still creates cache directories inside persistent source."
    },
    {
      "approach": "hardlink/symlink artifact farm",
      "reason": "Adds link/cross-filesystem/source mutation assumptions and traversal policy. Independent full copy is simpler for this rare fallback."
    },
    {
      "approach": "custom Pipeline/TransformersModel/SampleCache subclass or global monkeypatch",
      "reason": "Larger/private version-specific surface than public config plus owned artifact materialization."
    },
    {
      "approach": "purge or rewrite old source caches",
      "reason": "Would mutate user-owned persistent directories and could destroy unrelated results; unnecessary for isolation."
    },
    {
      "approach": "guess cache directories by16hex names and omit them while copying",
