    },
    {
      "id": "LC2",
      "case": "Seed original persistent source with known stale response cache/sentinel; snapshot full tree names/content/modes before evaluation.",
      "oracle": "Original tree exactly unchanged after success and after real pipeline failure; stale rows ignored; model/tokenizer refs in Pipeline are owned copy paths, config itself untouched."
    },
    {
      "id": "LC3",
      "case": "Read-only source model/tokenizer directories, including nested artifact directory and file symlink consistent with local HF cache layout; actual Pipeline inference.",
      "oracle": "Success without any source write, copied model root permits its cache, all owned trees removed. Verify process permissions actually enforce read-only where available; supplement path-event/snapshot proof without pretending chmod proves behavior under elevated privileges."
    },
    {
      "id": "LC4",
      "case": "Retain existing actual current-model export A->B case.",
      "oracle": "No double copy; current model state/mode/grad preserved, expected real metric change, temporary exports/cache/output removed."
    },
    {
      "id": "LC5",
      "case": "Real invalid TransformersModelConfig fatal/nonfatal runner path plus failure after cache creation/inference begins.",
      "oracle": "Original exception/error policy preserved; both result context keys cleared; partial copied model/output/cache removed; source unchanged. Instrument actual method to raise after genuine work only for cleanup branch, distinguish from full actual-metric pass."
    },
    {
      "id": "LC6",
      "case": "Real SampleCache with actual TransformersModelConfig for Hub-style relative ID and unique public cache_dir; no Hub network/model download necessary for this path arithmetic test.",
      "oracle": "Cache contained under each separate temporary output; no reads from other run. This validates cache-path mechanism only, not downloaded Hub-model inference; retain local real Pipeline proof separately."
    },
    {
      "id": "LC7",
      "case": "Same-directory copy dedup, separate local tokenizer, relative model path, copy/permission/disk failure at owned destination; unrelated external sentinel.",
      "oracle": "Exactly expected materialized references; partial owned work removed, source/unrelated paths never deleted, original cause propagated. Bounded helper tests may instrument copy failure, not replace inference acceptance."
    }
  ],
  "test_and_profile_handoff": "Actual-runtime author updates precise tests/llm_eval case inventory with local fallback/cache and missing-primary cases. Root binds accepted IDs to optional profile ledger after fresh implementation review. Existing fake core evaluator tests may need narrow expected cache_dir forwarding support, without replacing genuine runtime tests.",
