      "uv sync --locked --python 3.13 --no-default-groups --group dev --extra llm_eval",
      "uv run --no-sync --python 3.13 python -m pytest tests/llm_eval --test-profile=llm-eval",
      "uv run --locked --python 3.13 --extra llm_eval python <actual-evaluator-entrypoint>"
    ],
